const MAIL=require('./mail.js');
const mailCfg=()=>{db.mail=Object.assign({on:false,user:'',pass:'',fromName:'Engineering Project Manager',to:[],assignees:true,managers:true,repeat:false,appUrl:'',sent:{},log:[],failAt:0},db.mail||{});return db.mail};
const lanUrl=()=>{if(HOST!=='0.0.0.0'&&HOST!=='127.0.0.1')return'http://'+HOST+':'+PORT;for(const l of Object.values(os.networkInterfaces()))for(const i of l)if(i.family==='IPv4'&&!i.internal)return'http://'+i.address+':'+PORT;return'http://localhost:'+PORT};
const mailPub=()=>{const m=mailCfg();return{on:m.on,user:m.user,hasPass:!!m.pass,fromName:m.fromName,to:m.to,assignees:m.assignees,managers:m.managers,repeat:m.repeat,appUrl:m.appUrl||lanUrl(),log:m.log.slice(-15).reverse(),late:MAIL.lateItems(db,today()).length}};
const mlog=(m,o)=>{m.log.push(Object.assign({ts:new Date().toISOString()},o));if(m.log.length>60)m.log=m.log.slice(-60)};
let mailBusy=false;
async function mailRun(mode){const m=mailCfg();if(!m.user||!m.pass)throw new Error('Enter the Gmail address and the App Password first.');if(mailBusy)return{sent:0,busy:1};
  mailBusy=true;try{const td=today(),all=MAIL.lateItems(db,td),keyOf=it=>m.repeat?it.key+'@'+td:it.key;
    if(mode==='auto'){const live=new Set(all.map(keyOf));Object.keys(m.sent).forEach(k=>{if(!live.has(k))delete m.sent[k]})}
    const fresh=mode==='all'?all:all.filter(it=>!m.sent[keyOf(it)]);if(!fresh.length)return{sent:0,items:0};
    const map=MAIL.recipients(db,m,fresh,td);if(!map.size)return{sent:0,items:fresh.length,note:'No valid e-mail address to send to. Users need a real e-mail as User ID, or add extra recipients.'};
    const hist=Object.values(db.c.history||{}).sort((a,b)=>String(b.ts).localeCompare(String(a.ts))).slice(0,10);let sent=0;const errs=[];
    for(const [to,items] of map){items.sort((a,b)=>b.days-a.days);try{const b=MAIL.build(items,hist,m.appUrl||lanUrl(),'For '+to);await MAIL.smtpSend(m,[to],'EPM – '+items.length+' work item'+(items.length>1?'s':'')+' not completed by the end date',b.text,b.html);sent++;mlog(m,{to,n:items.length,ok:1,mode})}catch(e){const er=MAIL.nice(e);errs.push(er);mlog(m,{to,n:items.length,ok:0,err:er,mode})}}
    if(sent>0||!errs.length){fresh.forEach(it=>{m.sent[keyOf(it)]=Date.now()});m.failAt=0}else m.failAt=Date.now();
    save();return{sent,items:fresh.length,errors:errs}}finally{mailBusy=false}}
const mailTick=()=>{try{const m=db&&db.mail;if(!m||!m.on||!m.user||!m.pass)return;if(m.failAt&&Date.now()-m.failAt<600000)return;mailRun('auto').catch(e=>{m.failAt=Date.now();mlog(m,{ok:0,err:MAIL.nice(e),mode:'auto'});save()})}catch(e){}};

